L14_1.m_Talk_VTN = L15_1
L15_1 = "\228\189\134\230\136\145\232\191\189\232\184\170\229\137\141\232\190\136\228\185\139\229\137\141\239\188\140\230\136\145\230\151\169\229\176\177\230\131\179\232\191\135\229\137\141\232\190\136\230\156\137\229\143\175\232\131\189\229\176\177\230\152\175\229\143\151\229\174\179\232\128\133\239\188\140\232\128\140\228\184\141\230\152\175\229\135\182\230\137\139\227\128\130"
